// THE ATLAS (docs/design/WEB_ATLAS.md): every real-world place the old road novels used, reimagined as DSOA sites; the
// cast of fighters and rulers who live in them, as archetypes; the fights those places stage, as situations; and one real
// military installation per state, sized by its real footprint. DATA ONLY: nothing imports this file yet, it is not wired
// into the game. Rows are written in our own words and our own vocabulary (docs/design/WEB_FAN_SERVICE_BIBLE.md §3.3);
// real geography is ours to use, the series' invented place names, people and slang are not.
//
// Coordinates: lat/lon (WGS84, decimal degrees) are the real place. World x/z (metres, +x east, +z south, Phoenix at
// 0, 0) are DERIVED by tools/atlas-project.mjs from usmap.json and written into the generated block at the end of this
// file (ATLAS_XZ). Re-run `node tools/atlas-project.mjs` after editing any lat/lon; `--check` fails if the block is stale.
// `conf`: 'stated' = the place is named in public summaries; 'inferred' = only a region is named, the anchor is our pick.

// Who holds a place. `ruler` resolves through RULERS (docs/DIVIDED_STATES.md); the families are the seven of
// docs/WORLD_PILLARS.md Pillar 2; `remnant`, `dustwolves`, `drifters` and `infected` are engine faction ids (data/society.js).
export const HOLDERS = {
  ruler:            { name: 'the state\'s ruler', kind: 'ruler', note: 'resolves through RULERS by the row\'s state' },
  keyholder:        { name: 'a local Keyholder family', kind: 'local', note: 'one holdout, its own gate, water valve and odd laws (HOUSE RULES)' },
  remnant:          { name: 'The Federal Remnant', kind: 'family', engine: 'remnant' },
  free_counties:    { name: 'The Free Counties', kind: 'family' },
  corporate:        { name: 'The Corporate Corridor', kind: 'family' },
  crimson_road:     { name: 'The Crimson Road', kind: 'family' },
  green_belt:       { name: 'The Green Belt', kind: 'family' },
  dead_zone:        { name: 'The Capitol Dead Zone', kind: 'family', note: 'no ruler: scavengers and the highest ambient danger' },
  broadcast_church: { name: 'The Broadcast Church', kind: 'family' },
  dustwolves:       { name: 'The Dustwolves', kind: 'engine', engine: 'dustwolves' },
  haulers:          { name: 'sutlers and haulers', kind: 'trade', note: 'the convoy trade; no flag, a long memory' },
  corsairs:         { name: 'the corsairs', kind: 'raiders', note: 'sea, gulf and lake raiders; the Crimson Road\'s water cousins' },
  slavers:          { name: 'the chain trade', kind: 'raiders', note: 'buyers, breeders and press gangs; every ruler pretends not to deal with them' },
  labkin:           { name: 'the Lab Kin', kind: 'enclave', note: 'descendants of trial-lab staff who never left their sealed labs (LORE_BIBLE §6)' },
  machine:          { name: 'the continuity network', kind: 'machine', note: 'automated Carousel nodes; nobody human at home (LORE_BIBLE §4)' },
  infected:         { name: 'the infected', kind: 'engine', engine: 'infected' },
  drifters:         { name: 'Drifters', kind: 'engine', engine: 'drifters', note: 'the loose road folk; the player\'s crew counts as drifters' },
  creatures:        { name: 'failed-fix animals', kind: 'wild' },
  contested:        { name: 'contested', kind: 'war', note: 'two or more holders fighting for it right now' },
  none:             { name: 'nobody', kind: 'empty' },
};

