// ---------------------------------------------------------------------------------------------------------------------
// (a) SITES. One row per real place. kind: holdout | station (a Carousel Station, our bunker with a ring) | depot (a
// sealed store, no ring) | lab (a trial lab) | ruin | hazard | route | arena | wilds. abroad: off the mainland grid
// (a misjump can still throw you there). biome uses the usmap legend (plains, desert, forest, mountains, swamp, scrub,
// farmland, urban, water, ocean) plus arctic, island and jungle for places off the grid.
const S = (id, name, real, lat, lon, state, kind, situation, biome, terrain, holder, what, conf = 'stated') =>
  ({ id, name, real, lat, lon, state, kind, situation, biome, terrain, holder, what, conf });

