// (d) MILITARY INSTALLATIONS: one real installation per state. area_km2 is the real footprint (areaSrc: wiki = the
// installation's Wikipedia article; cdp = the Census-designated-place area, used where no total is published; other =
// a public source named in the study notes). kind: army | air | navy | guard | depot | space. dsoa: abandoned |
// remnant (a Federal Remnant garrison) | raider (a raider-held armory) | overrun (infected or creatures) | ruler (held
// by the state's ruler) | automated (the continuity network) | contested. carousel: the canon ring row (game/data/carousel.json).
const B = (state, id, name, lat, lon, area_km2, areaSrc, kind, dsoa, holder, what, carousel = null) =>
  ({ state, id, name, lat, lon, area_km2, areaSrc, kind, dsoa, holder, what, carousel });

