// The footprint rule (WEB_ATLAS.md §4 F2): land compresses with the road law (1:14), buildings do not. A base's fence
// encloses real_area / S^2, as a square side; the built compound is clamped between OUTPOST NINE (the smallest base we
// ship) and a metro (decision 5, WEB_STREAMING.md).
export const FOOTPRINT = { S: 14, minSide: 64, maxSide: 3000 };
export function footprint(area_km2, f = FOOTPRINT) {
  const area_m2 = area_km2 * 1e6 / (f.S * f.S);
  const side = Math.sqrt(area_m2);
  return { area_m2: Math.round(area_m2), side_m: Math.round(side), built_m: Math.round(Math.min(f.maxSide, Math.max(f.minSide, side))) };
}

